#include "engine/ControllerMap.h"
#include "ControllerData.h"     // generated by juce_add_binary_data (see CMakeLists.txt)

namespace ikaros
{

namespace
{
    // The names the profile files use.
    const std::pair<const char*, ControllerAction> actionNames[]
    {
        { "play", ControllerAction::play },               { "stop", ControllerAction::stop },
        { "playStop", ControllerAction::playStop },
        { "record", ControllerAction::record },           { "loop", ControllerAction::loop },
        { "metronome", ControllerAction::metronome },     { "undo", ControllerAction::undo },
        { "redo", ControllerAction::redo },               { "rewind", ControllerAction::rewind },
        { "fastForward", ControllerAction::fastForward }, { "goToStart", ControllerAction::goToStart },
        { "previousTrack", ControllerAction::previousTrack }, { "nextTrack", ControllerAction::nextTrack },
        { "muteTrack", ControllerAction::muteTrack },     { "soloTrack", ControllerAction::soloTrack },
        { "armTrack", ControllerAction::armTrack },
        { "volume", ControllerAction::volume },           { "pan", ControllerAction::pan },
        { "reverbSend", ControllerAction::reverbSend },   { "delaySend", ControllerAction::delaySend },
        { "soundKnob", ControllerAction::soundKnob },     { "masterVolume", ControllerAction::masterVolume },
        { "selectTrack", ControllerAction::selectTrack }, { "moveBars", ControllerAction::moveBars },
        { "faderBank", ControllerAction::faderBank },
    };

    std::optional<ControllerAction> findAction (const juce::String& name)
    {
        for (auto [text, action] : actionNames)
            if (name == text)
                return action;

        return std::nullopt;
    }

    std::optional<ControllerProfile::Control::Type> findType (const juce::String& name)
    {
        using Type = ControllerProfile::Control::Type;

        if (name == "button")   return Type::button;
        if (name == "knob")     return Type::knob;
        if (name == "encoder")  return Type::encoder;
        return std::nullopt;
    }
}

std::optional<ControllerProfile> ControllerProfile::fromJson (const juce::String& text)
{
    const auto json = juce::JSON::parse (text);

    if (! json.isObject())
        return std::nullopt;

    ControllerProfile profile;
    profile.name = json["name"].toString();

    if (auto* ports = json["ports"].getArray())
        for (auto& port : *ports)
            profile.ports.add (port.toString());

    if (auto* ports = json["mackiePorts"].getArray())
        for (auto& port : *ports)
            profile.mackiePorts.add (port.toString());

    profile.faders = juce::jlimit (1, 8, (int) json.getProperty ("faders", 8));

    if (auto* controls = json["controls"].getArray())
    {
        for (auto& c : *controls)
        {
            const auto action = findAction (c["action"].toString());

            if (! action)
                continue;

            Control control;

            // A system message: its bytes, written in hex.
            if (c.hasProperty ("sysex"))
            {
                control.sysex.loadFromHexString (c["sysex"].toString());   // skips the spaces
                control.action = *action;
                control.index = juce::jmax (0, (int) c.getProperty ("index", 0));

                auto* bytes = static_cast<const juce::uint8*> (control.sysex.getData());

                if (control.sysex.getSize() >= 3 && bytes[0] == 0xf0 && bytes[control.sysex.getSize() - 1] == 0xf7)
                    profile.controls.push_back (control);

                continue;
            }

            // A program change.
            if (c.hasProperty ("pgm"))
            {
                control.program = c["pgm"];
                control.channel = juce::jlimit (0, 16, (int) c.getProperty ("channel", 0));
                control.action = *action;
                control.index = juce::jmax (0, (int) c.getProperty ("index", 0));

                if (control.program >= 0 && control.program <= 127)
                    profile.controls.push_back (control);

                continue;
            }

            const auto type = findType (c["type"].toString());
            const int number = c.getProperty ("cc", -1);

            if (! type || number < 0 || number > 127)
                continue;

            control.controller = number;
            control.channel = juce::jlimit (0, 16, (int) c.getProperty ("channel", 0));
            control.type = *type;
            control.action = *action;
            control.index = juce::jmax (0, (int) c.getProperty ("index", 0));
            control.alsoMackie = (bool) c.getProperty ("alsoMackie", false);
            profile.controls.push_back (control);
        }
    }

    if (profile.name.isEmpty() || profile.ports.isEmpty())
        return std::nullopt;

    return profile;
}

static bool listsPort (const juce::StringArray& ports, const juce::String& portName)
{
    for (auto& port : ports)
    {
        const auto pattern = port.trim();

        if (pattern.endsWithChar ('*') ? portName.trim().startsWithIgnoreCase (pattern.dropLastCharacters (1))
                                       : pattern.equalsIgnoreCase (portName.trim()))
            return true;
    }

    return false;
}

bool ControllerProfile::isFor (const juce::String& portName) const          { return listsPort (ports, portName); }
bool ControllerProfile::isForMackie (const juce::String& portName) const    { return listsPort (mackiePorts, portName); }

const ControllerProfile::Control* ControllerProfile::find (const juce::MidiMessage& m) const
{
    if (m.isSysEx())
    {
        // getRawData() is the whole message, F0 to F7.
        const juce::MemoryBlock bytes (m.getRawData(), (size_t) m.getRawDataSize());

        for (auto& c : controls)
            if (c.sysex == bytes)
                return &c;

        return nullptr;
    }

    if (m.isProgramChange())
    {
        for (auto& c : controls)
            if (c.program == m.getProgramChangeNumber() && (c.channel == 0 || c.channel == m.getChannel()))
                return &c;

        return nullptr;
    }

    if (! m.isController())
        return nullptr;

    for (auto& c : controls)
        if (c.sysex.isEmpty() && c.program < 0 && c.controller == m.getControllerNumber() && (c.channel == 0 || c.channel == m.getChannel()))
            return &c;

    return nullptr;
}

std::vector<ControllerProfile> ControllerProfile::getBuiltIn()
{
    std::vector<ControllerProfile> builtIn;

    // juce_add_binary_data lists every file it embedded by name.
    for (int i = 0; i < ControllerData::namedResourceListSize; ++i)
    {
        int size = 0;
        const auto* data = ControllerData::getNamedResource (ControllerData::namedResourceList[i], size);

        if (auto profile = fromJson (juce::String::fromUTF8 (data, size)))
            builtIn.push_back (std::move (*profile));
        else
            jassertfalse;   // a broken file in resources/controllers
    }

    return builtIn;
}

//==============================================================================
void ControllerMap::setProfiles (std::vector<ControllerProfile> newProfiles)
{
    const juce::ScopedLock sl (lock);
    profiles = std::move (newProfiles);
}

std::optional<ControllerProfile> ControllerMap::getProfileForMackiePort (const juce::String& portName) const
{
    const juce::ScopedLock sl (lock);

    for (auto& p : profiles)
        if (p.isForMackie (portName))
            return p;

    return std::nullopt;
}

std::optional<ControllerProfile> ControllerMap::getProfileFor (const juce::String& portName) const
{
    const juce::ScopedLock sl (lock);

    for (auto& p : profiles)
        if (p.isFor (portName))
            return p;

    return std::nullopt;
}

bool ControllerMap::handleMessage (const juce::String& portName, const juce::MidiMessage& m)
{
    using Type = ControllerProfile::Control::Type;

    if (! m.isController() && ! m.isSysEx() && ! m.isProgramChange())
        return false;   // notes, pitch bend etc. always play

    const juce::ScopedLock sl (lock);

    for (auto& profile : profiles)
    {
        if (! profile.isFor (portName))
            continue;

        auto* control = profile.find (m);

        if (control == nullptr)
            return false;

        // A system message or program change just does its action.
        const int value = m.isController() ? m.getControllerValue() : 127;

        // A button's release does nothing, but is swallowed like the press.
        if (control->type == Type::button && value == 0)
            return true;

        ControllerEvent e;
        e.action = control->action;
        e.index = control->index;
        e.controller = control->controller;
        e.value = (float) value / 127.0f;
        e.steps = control->type == Type::encoder ? value - 64 : 0;
        e.alsoMackie = control->alsoMackie;

        if (control->type != Type::encoder || e.steps != 0)
            events.push_back (e);

        return true;
    }

    return false;
}

std::vector<ControllerEvent> ControllerMap::takeEvents()
{
    const juce::ScopedLock sl (lock);
    std::vector<ControllerEvent> taken;
    std::swap (taken, events);   // leaves it empty
    return taken;
}

} // namespace ikaros
